from __future__ import annotations
import argparse, copy, hashlib, json, pathlib
from datetime import datetime, timezone, timedelta
TZ=timezone(timedelta(hours=3))
def load(p): return json.loads(pathlib.Path(p).read_text(encoding='utf-8'))
def digest(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--spec',required=True);ap.add_argument('--candidate-out',required=True);ap.add_argument('--canonical-out',required=True);ap.add_argument('--audit-out',required=True);a=ap.parse_args()
    s=load(a.spec);parent=load(s['parent_state']);ev=load(s['new_evidence']);ni=[x for x in ev['candidate_results'] if x.get('source_word_after_scoring')=='NI' and x.get('role')=='RIGHT_NUMERIC']
    pre={'parent_v2_22':parent.get('version')=='v2.22' and parent.get('status')=='CURRENT_CANONICAL_RESEARCH_STATE','status_exact':ev.get('status')==s['required_status'],'family_2':ev.get('candidate_family_size')==2,'survivors_0':ev.get('survivor_count')==0,'no_blind_credit':ev['leakage_and_credit'].get('blind_confirmation_credit') is False,'no_independent_confirmation':ev['leakage_and_credit'].get('independent_confirmation_claimed') is False,'ni_one':len(ni)==1,'ni_not_survive':len(ni)==1 and ni[0].get('REGION_CONDITIONED_SURVIVAL') is False,'ni_p_exact':len(ni)==1 and ni[0].get('region_conditioned_p')==s['required']['NI_RIGHT_region_conditioned_p'],'ni_q_exact':len(ni)==1 and ni[0].get('region_conditioned_BH_q')==s['required']['NI_RIGHT_region_conditioned_BH_q'],'meaning_false':ev['epistemic_gate'].get('meaning_established') is False,'decipherment_false':ev['epistemic_gate'].get('decipherment_established') is False}
